function validate([nums, k]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value in nums is between 1 and 10^5.';
  if (!Number.isInteger(k) || k < 1 || k > 100000) return 'k is between 1 and 10^5.';
  return null;
}

