function lengthOfLIS(nums, k) {
  let size = 1;
  for (const num of nums) {
    size = Math.max(size, num + 1);
  }
  const tree = new Array(2 * size).fill(0);
  let best = 0;

  for (const num of nums) {
    let left = Math.max(0, num - k) + size;
    let right = num + size;
    let longest = 0;
    while (left < right) {
      if (left & 1) {
        longest = Math.max(longest, tree[left]);
        left++;
      }
      if (right & 1) {
        right--;
        longest = Math.max(longest, tree[right]);
      }
      left >>= 1;
      right >>= 1;
    }

    let node = num + size;
    tree[node] = Math.max(tree[node], longest + 1);
    while (node > 1) {
      node >>= 1;
      tree[node] = Math.max(tree[2 * node], tree[2 * node + 1]);
    }
    best = Math.max(best, longest + 1);
  }
  return best;
}

