function lengthOfLIS(nums, k) {
  // Classic O(n^2) DP over positions: ends[i] is the longest valid subsequence ending at index i.
  const ends = [];
  let answer = 0;
  for (let i = 0; i < nums.length; i++) {
    ends[i] = 1;
    for (let j = 0; j < i; j++) {
      const diff = nums[i] - nums[j];
      if (diff > 0 && diff <= k) ends[i] = Math.max(ends[i], ends[j] + 1);
    }
    answer = Math.max(answer, ends[i]);
  }
  return answer;
}

