function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    // Mix a narrow value range (long chains) with the full range (sparse values).
    const top = rand() < 0.5 ? int(500, 5000) : 100000;
    const nums = Array.from({ length: 2000 }, () => int(1, top));
    const k = rand() < 0.2 ? int(1000, 100000) : int(1, 60);
    return [nums, k];
  }
  const n = int(1, 10);
  const top = rand() < 0.15 ? 100000 : int(1, 20);
  const nums = Array.from({ length: n }, () => int(1, top));
  const k = rand() < 0.15 ? 100000 : int(1, 8);
  return [nums, k];
}
